using Microsoft.AspNetCore.Localization;
using Microsoft.Extensions.Options;
using System.Globalization;

var builder = WebApplication.CreateBuilder(args);

// Register MVC with localization support for Views and DataAnnotations
builder.Services.AddControllersWithViews()
    .AddViewLocalization(LanguageViewLocationExpanderFormat.Suffix)
    .AddDataAnnotationsLocalization();

// Configure supported cultures
builder.Services.Configure<RequestLocalizationOptions>(options =>
{
    var supportedCultures = new[]
    {
        new CultureInfo("en-US"),
        new CultureInfo("fr"),
        new CultureInfo("es")
    };

    options.DefaultRequestCulture = new RequestCulture("en-US");
    options.SupportedCultures = supportedCultures;
    options.SupportedUICultures = supportedCultures;
});

// Optional: store all resource files in a shared 'Resources' folder
builder.Services.AddLocalization(options =>
{
    options.ResourcesPath = "Resources";
});

var app = builder.Build();

// ... other middleware (HttpsRedirection, StaticFiles, Routing)

app.UseRouting();

// Enable request localization — must come before Authorization & MapControllers
var locOptions = app.Services.GetRequiredService<IOptions<RequestLocalizationOptions>>();
app.UseRequestLocalization(locOptions.Value);

app.UseAuthorization();
app.MapControllers();
app.MapDefaultControllerRoute();
app.Run();

using System.ComponentModel.DataAnnotations;

namespace AspNetLocalizationDemo.Models;

public class JobApplication
{
    [Required(ErrorMessage = "Name is required")]
    [Display(Name = "Full Name")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required")]
    [EmailAddress(ErrorMessage = "Invalid email format")]
    [Display(Name = "Email Address")]
    public string Email { get; set; } = string.Empty;

    [Range(0, 50, ErrorMessage = "Experience must be between {0} and {1} years")]
    [Display(Name = "Years of Experience")]
    public int Experience { get; set; }

    [Display(Name = "Date of Birth")]
    public DateTime DateOfBirth { get; set; }

    [Required(ErrorMessage = "You must accept the terms")]
    [Display(Name = "Terms and Conditions")]
    public bool TermsAccepted { get; set; }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Localization;

namespace AspNetLocalizationDemo.Controllers;

public class HomeController : Controller
{
    private readonly IStringLocalizer<HomeController> _localizer;

    public HomeController(IStringLocalizer<HomeController> localizer)
    {
        _localizer = localizer;
    }

    [HttpGet]
    public IActionResult Index()
    {
        return View();
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public IActionResult Index(JobApplication model)
    {
        if (ModelState.IsValid)
        {
            // Pulls from HomeController.fr.resx or HomeController.es.resx
            ViewBag.SuccessMessage = _localizer["Application submitted successfully"];
            return View("Success");
        }
        return View(model);
    }
}

